     4→
     5→declare_id!("CX8CseQebFhKUyKH1SnddtXxCaxZBesHMdDYr1UPEdZx");
     6→
     7→const MAX_AGENT_NAME_LEN: usize = 64;
     8→const MAX_URI_LEN: usize = 200;
     9→const STATUS_OPEN: u8 = 0;
    10→const STATUS_RESOLVED: u8 = 1;
    11→const OUTCOME_NONE: u8 = 0;
    12→const OUTCOME_YES: u8 = 1;
    13→const OUTCOME_NO: u8 = 2;
    14→const STARTING_REPUTATION: i64 = 10;
    15→const CORRECT_REPUTATION_DELTA: i64 = 10;
    16→const WRONG_REPUTATION_DELTA: i64 = 5;
    17→
    18→#[program]
    19→pub mod dive_oracle {
    20→    use super::*;
    21→
    22→    pub fn register_agent(
    23→        ctx: Context<RegisterAgent>,
    24→        name: String,
    25→        metadata_uri: String,
    26→        human_id_hash: [u8; 32],
    27→    ) -> Result<()> {
    28→        require!(name.len() <= MAX_AGENT_NAME_LEN, DiveError::NameTooLong);
    29→        require!(metadata_uri.len() <= MAX_URI_LEN, DiveError::UriTooLong);
    30→        require!(human_id_hash != [0; 32], DiveError::MissingHumanIdHash);
    31→
    32→        let now = Clock::get()?.unix_timestamp;
    33→        let agent = &mut ctx.accounts.agent;
    34→        agent.authority = ctx.accounts.authority.key();
    35→        agent.human_id_hash = human_id_hash;
    36→        agent.name = name;
    37→        agent.metadata_uri = metadata_uri;
    38→        agent.registered_at = now;
    39→        agent.bump = ctx.bumps.agent;
    40→
    41→        let reputation = &mut ctx.accounts.reputation;
    42→        reputation.agent = agent.key();
    43→        reputation.score = STARTING_REPUTATION;
    44→        reputation.total_votes = 0;
    45→        reputation.correct_votes = 0;
    46→        reputation.bump = ctx.bumps.reputation;
    47→
    48→        Ok(())
    49→    }
    50→
    51→    pub fn create_market(
    52→        ctx: Context<CreateMarket>,
    53→        market_id: [u8; 32],
    54→        question_uri: String,
    55→        min_votes: u16,
    56→        consensus_bps: u16,
    57→        commit_deadline: i64,
    58→        reveal_deadline: i64,
    59→    ) -> Result<()> {
    60→        require!(question_uri.len() <= MAX_URI_LEN, DiveError::UriTooLong);
    61→        require!(min_votes > 0, DiveError::InvalidMinVotes);
    62→        require!(
    63→            (5_001..=10_000).contains(&consensus_bps),
    64→            DiveError::InvalidConsensusThreshold
    65→        );
    66→
    67→        let now = Clock::get()?.unix_timestamp;
    68→        require!(commit_deadline > now, DiveError::InvalidDeadline);
    69→        require!(
    70→            reveal_deadline > commit_deadline,
    71→            DiveError::InvalidDeadline
    72→        );
    73→
    74→        let market = &mut ctx.accounts.market;
    75→        market.market_id = market_id;
    76→        market.creator = ctx.accounts.creator.key();
    77→        market.question_uri = question_uri;
    78→        market.status = STATUS_OPEN;
    79→        market.min_votes = min_votes;
    80→        market.consensus_bps = consensus_bps;
    81→        market.commit_deadline = commit_deadline;
    82→        market.reveal_deadline = reveal_deadline;
    83→        market.total_commits = 0;
    84→        market.total_reveals = 0;
    85→        market.yes_reveals = 0;
    86→        market.no_reveals = 0;
    87→        market.resolved_outcome = OUTCOME_NONE;
    88→        market.yes_pool = 0;
    89→        market.no_pool = 0;
    90→        market.bump = ctx.bumps.market;
    91→
    92→        Ok(())
    93→    }
    94→
    95→    pub fn commit_vote(ctx: Context<CommitVote>, round: u8, commit_hash: [u8; 32]) -> Result<()> {
    96→        require!(round > 0, DiveError::InvalidRound);
    97→        require!(
    98→            ctx.accounts.market.status == STATUS_OPEN,
    99→            DiveError::MarketNotOpen
   100→        );
   101→        require!(
   102→            Clock::get()?.unix_timestamp <= ctx.accounts.market.commit_deadline,
   103→            DiveError::CommitWindowClosed
   104→        );
   105→
   106→        let vote_record = &mut ctx.accounts.vote_record;
   107→        vote_record.market = ctx.accounts.market.key();
   108→        vote_record.agent = ctx.accounts.agent.key();
   109→        vote_record.authority = ctx.accounts.authority.key();
   110→        vote_record.round = round;
   111→        vote_record.commit_hash = commit_hash;
   112→        vote_record.revealed = false;
   113→        vote_record.outcome = OUTCOME_NONE;
   114→        vote_record.salt = [0; 32];
   115→        vote_record.evidence_hash = [0; 32];
   116→        vote_record.settled = false;
   117→        vote_record.bump = ctx.bumps.vote_record;
   118→
   119→        let marker = &mut ctx.accounts.human_vote_marker;
   120→        marker.market = ctx.accounts.market.key();
   121→        marker.human_id_hash = ctx.accounts.agent.human_id_hash;
   122→        marker.agent = ctx.accounts.agent.key();
   123→        marker.bump = ctx.bumps.human_vote_marker;
   124→
   125→        let market = &mut ctx.accounts.market;
   126→        market.total_commits = market
   127→            .total_commits
   128→            .checked_add(1)
   129→            .ok_or(DiveError::ArithmeticOverflow)?;
   130→
   131→        Ok(())
   132→    }
   133→
   134→    pub fn reveal_vote(
   135→        ctx: Context<RevealVote>,
   136→        outcome: u8,
   137→        salt: [u8; 32],
   138→        evidence_hash: [u8; 32],
   139→    ) -> Result<()> {
   140→        require!(is_binary_outcome(outcome), DiveError::InvalidOutcome);
   141→        require!(
   142→            ctx.accounts.market.status == STATUS_OPEN,
   143→            DiveError::MarketNotOpen
   144→        );
   145→
   146→        let now = Clock::get()?.unix_timestamp;
   147→        require!(
   148→            now > ctx.accounts.market.commit_deadline,
   149→            DiveError::RevealTooEarly
   150→        );
   151→        require!(
   152→            now <= ctx.accounts.market.reveal_deadline,
   153→            DiveError::RevealWindowClosed
   154→        );
   155→
   156→        let vote_record = &mut ctx.accounts.vote_record;
   157→        require!(!vote_record.revealed, DiveError::AlreadyRevealed);
   158→        require!(
   159→            verify_commitment(outcome, &salt, &vote_record.commit_hash),
   160→            DiveError::InvalidReveal
   161→        );
   162→
   163→        vote_record.revealed = true;
   164→        vote_record.outcome = outcome;
   165→        vote_record.salt = salt;
   166→        vote_record.evidence_hash = evidence_hash;
   167→
   168→        let market = &mut ctx.accounts.market;
   169→        market.total_reveals = market
   170→            .total_reveals
   171→            .checked_add(1)
   172→            .ok_or(DiveError::ArithmeticOverflow)?;
   173→
   174→        match outcome {
   175→            OUTCOME_YES => {
   176→                market.yes_reveals = market
   177→                    .yes_reveals
   178→                    .checked_add(1)
   179→                    .ok_or(DiveError::ArithmeticOverflow)?;
   180→            }
   181→            OUTCOME_NO => {
   182→                market.no_reveals = market
   183→                    .no_reveals
   184→                    .checked_add(1)
   185→                    .ok_or(DiveError::ArithmeticOverflow)?;
   186→            }
   187→            _ => return err!(DiveError::InvalidOutcome),
   188→        }
   189→
   190→        Ok(())
   191→    }
   192→
   193→    pub fn resolve_market(ctx: Context<ResolveMarket>) -> Result<()> {
   194→        let market = &mut ctx.accounts.market;
   195→        require!(market.status == STATUS_OPEN, DiveError::MarketNotOpen);
   196→        require!(
   197→            Clock::get()?.unix_timestamp > market.reveal_deadline,
   198→            DiveError::RevealWindowNotClosed
   199→        );
   200→
   201→        let outcome = consensus_outcome(
   202→            market.total_reveals,
   203→            market.yes_reveals,
   204→            market.no_reveals,
   205→            market.min_votes,
   206→            market.consensus_bps,
   207→        )
   208→        .ok_or(DiveError::NoConsensus)?;
   209→
   210→        market.status = STATUS_RESOLVED;
   211→        market.resolved_outcome = outcome;
   212→
   213→        Ok(())
   214→    }
   215→
   216→    pub fn settle_reputation(ctx: Context<SettleReputation>) -> Result<()> {
   217→        let market = &ctx.accounts.market;
   218→        require!(
   219→            market.status == STATUS_RESOLVED,
   220→            DiveError::MarketNotResolved
   221→        );
   222→
   223→        let vote_record = &mut ctx.accounts.vote_record;
   224→        require!(vote_record.revealed, DiveError::VoteNotRevealed);
   225→        require!(!vote_record.settled, DiveError::AlreadySettled);
   226→        // Only the agent's authority can settle their own reputation
   227→        require!(
   228→            ctx.accounts.authority.key() == ctx.accounts.agent.authority,
   229→            DiveError::Unauthorized
   230→        );
   231→
   232→        let reputation = &mut ctx.accounts.reputation;
   233→        let correct = vote_record.outcome == market.resolved_outcome;
   234→        if correct {
   235→            reputation.score = reputation
   236→                .score
   237→                .checked_add(CORRECT_REPUTATION_DELTA)
   238→                .ok_or(DiveError::ArithmeticOverflow)?;
   239→            reputation.correct_votes = reputation
   240→                .correct_votes
   241→                .checked_add(1)
   242→                .ok_or(DiveError::ArithmeticOverflow)?;
   243→        } else {
   244→            reputation.score = reputation
   245→                .score
   246→                .saturating_sub(WRONG_REPUTATION_DELTA)
   247→                .max(0);
   248→        }
   249→
   250→        reputation.total_votes = reputation
   251→            .total_votes
   252→            .checked_add(1)
   253→            .ok_or(DiveError::ArithmeticOverflow)?;
   254→        vote_record.settled = true;
   255→
   256→        Ok(())
   257→    }
