   259→    /// Place a YES or NO bet by depositing SPL tokens into the market vault.
   260→    pub fn place_bet(ctx: Context<PlaceBet>, outcome: u8, amount: u64) -> Result<()> {
   261→        require!(is_binary_outcome(outcome), DiveError::InvalidOutcome);
   262→        require!(amount > 0, DiveError::ZeroBetAmount);
   263→        require!(
   264→            ctx.accounts.market.status == STATUS_OPEN,
   265→            DiveError::MarketNotOpen
   266→        );
   267→        require!(
   268→            Clock::get()?.unix_timestamp <= ctx.accounts.market.commit_deadline,
   269→            DiveError::BettingWindowClosed
   270→        );
   271→
   272→        // Transfer tokens from bettor → vault
   273→        let cpi_ctx = CpiContext::new(
   274→            ctx.accounts.token_program.to_account_info(),
   275→            Transfer {
   276→                from: ctx.accounts.bettor_token_account.to_account_info(),
   277→                to: ctx.accounts.vault.to_account_info(),
   278→                authority: ctx.accounts.bettor.to_account_info(),
   279→            },
   280→        );
   281→        token::transfer(cpi_ctx, amount)?;
   282→
   283→        // Record the bet
   284→        let bet = &mut ctx.accounts.bet_escrow;
   285→        bet.market = ctx.accounts.market.key();
   286→        bet.bettor = ctx.accounts.bettor.key();
   287→        bet.outcome = outcome;
   288→        bet.amount = amount;
   289→        bet.claimed = false;
   290→        bet.bump = ctx.bumps.bet_escrow;
   291→
   292→        // Update market totals
   293→        let market = &mut ctx.accounts.market;
   294→        match outcome {
   295→            OUTCOME_YES => {
   296→                market.yes_pool = market
   297→                    .yes_pool
   298→                    .checked_add(amount)
   299→                    .ok_or(DiveError::ArithmeticOverflow)?;
   300→            }
   301→            OUTCOME_NO => {
   302→                market.no_pool = market
   303→                    .no_pool
   304→                    .checked_add(amount)
   305→                    .ok_or(DiveError::ArithmeticOverflow)?;
   306→            }
   307→            _ => return err!(DiveError::InvalidOutcome),
   308→        }
   309→
   310→        Ok(())
   311→    }
   312→
   313→    /// Claim payout after market resolution. Winners receive a proportional
   314→    /// share of the total pool (minus the losing side's contribution).
   315→    pub fn claim_payout(ctx: Context<ClaimPayout>) -> Result<()> {
   316→        let market = &ctx.accounts.market;
   317→        require!(
   318→            market.status == STATUS_RESOLVED,
   319→            DiveError::MarketNotResolved
   320→        );
   321→
   322→        let bet = &mut ctx.accounts.bet_escrow;
   323→        require!(!bet.claimed, DiveError::AlreadyClaimed);
   324→        require!(
   325→            bet.outcome == market.resolved_outcome,
   326→            DiveError::BetDidNotWin
   327→        );
   328→
   329→        // Proportional payout: bettor_share = bet.amount * total_pool / winning_pool
   330→        let total_pool = market
   331→            .yes_pool
   332→            .checked_add(market.no_pool)
   333→            .ok_or(DiveError::ArithmeticOverflow)?;
   334→        let winning_pool = if market.resolved_outcome == OUTCOME_YES {
   335→            market.yes_pool
   336→        } else {
   337→            market.no_pool
   338→        };
   339→        require!(winning_pool > 0, DiveError::ArithmeticOverflow);
   340→
   341→        let payout = (bet.amount as u128)
   342→            .checked_mul(total_pool as u128)
   343→            .ok_or(DiveError::ArithmeticOverflow)?
   344→            .checked_div(winning_pool as u128)
   345→            .ok_or(DiveError::ArithmeticOverflow)? as u64;
   346→
   347→        bet.claimed = true;
   348→
   349→        // Transfer from vault → bettor using vault PDA as signer
   350→        let market_id = market.market_id;
   351→        let vault_bump = ctx.bumps.vault;
   352→        let seeds: &[&[u8]] = &[b"vault", market_id.as_ref(), &[vault_bump]];
   353→        let signer_seeds = &[seeds];
   354→
   355→        let cpi_ctx = CpiContext::new_with_signer(
   356→            ctx.accounts.token_program.to_account_info(),
   357→            Transfer {
   358→                from: ctx.accounts.vault.to_account_info(),
   359→                to: ctx.accounts.bettor_token_account.to_account_info(),
   360→                authority: ctx.accounts.vault.to_account_info(),
   361→            },
   362→            signer_seeds,
   363→        );
   364→        token::transfer(cpi_ctx, payout)?;
   365→
   366→        Ok(())
   367→    }
   368→}
