   575→#[derive(Accounts)]
   576→pub struct PlaceBet<'info> {
   577→    #[account(mut)]
   578→    pub market: Account<'info, Market>,
   579→    /// Vault token account owned by the vault PDA
   580→    #[account(
   581→        init_if_needed,
   582→        payer = bettor,
   583→        token::mint = mint,
   584→        token::authority = vault,
   585→        seeds = [b"vault", market.market_id.as_ref()],
   586→        bump
   587→    )]
   588→    pub vault: Account<'info, TokenAccount>,
   589→    /// Bettor's source token account
   590→    #[account(mut, token::mint = mint, token::authority = bettor)]
   591→    pub bettor_token_account: Account<'info, TokenAccount>,
   592→    /// One BetEscrow per bettor per market
   593→    #[account(
   594→        init,
   595→        payer = bettor,
   596→        space = 8 + BetEscrow::INIT_SPACE,
   597→        seeds = [b"bet", market.key().as_ref(), bettor.key().as_ref()],
   598→        bump
   599→    )]
   600→    pub bet_escrow: Account<'info, BetEscrow>,
   601→    pub mint: Account<'info, Mint>,
   602→    #[account(mut)]
   603→    pub bettor: Signer<'info>,
   604→    pub token_program: Program<'info, Token>,
   605→    pub system_program: Program<'info, System>,
   606→}
   607→
   608→#[derive(Accounts)]
   609→pub struct ClaimPayout<'info> {
   610→    pub market: Account<'info, Market>,
   611→    /// Vault PDA — authority over the vault token account
   612→    #[account(
   613→        mut,
   614→        token::mint = mint,
   615→        token::authority = vault,
   616→        seeds = [b"vault", market.market_id.as_ref()],
   617→        bump
   618→    )]
   619→    pub vault: Account<'info, TokenAccount>,
   620→    /// Bettor's destination token account
   621→    #[account(mut, token::mint = mint, token::authority = bettor)]
   622→    pub bettor_token_account: Account<'info, TokenAccount>,
   623→    #[account(
   624→        mut,
   625→        has_one = market,
   626→        has_one = bettor,
   627→        seeds = [b"bet", market.key().as_ref(), bettor.key().as_ref()],
   628→        bump = bet_escrow.bump,
   629→        close = bettor
   630→    )]
   631→    pub bet_escrow: Account<'info, BetEscrow>,
   632→    pub mint: Account<'info, Mint>,
   633→    pub bettor: Signer<'info>,
   634→    pub token_program: Program<'info, Token>,
   635→}
   636→
   637→#[error_code]
   638→pub enum DiveError {
   639→    #[msg("Agent name exceeds maximum length")]
   640→    NameTooLong,
   641→    #[msg("URI exceeds maximum length")]
   642→    UriTooLong,
   643→    #[msg("Agent registration requires a non-zero human ID hash")]
   644→    MissingHumanIdHash,
   645→    #[msg("Minimum vote count must be greater than zero")]
   646→    InvalidMinVotes,
   647→    #[msg("Consensus threshold must be >50% and <=100%")]
   648→    InvalidConsensusThreshold,
   649→    #[msg("Invalid commit/reveal deadline configuration")]
   650→    InvalidDeadline,
   651→    #[msg("Market is not open")]
   652→    MarketNotOpen,
   653→    #[msg("Commit window is closed")]
   654→    CommitWindowClosed,
   655→    #[msg("Reveal attempted before commit deadline")]
   656→    RevealTooEarly,
   657→    #[msg("Reveal window is closed")]
   658→    RevealWindowClosed,
   659→    #[msg("Invalid vote outcome")]
   660→    InvalidOutcome,
   661→    #[msg("Vote has already been revealed")]
   662→    AlreadyRevealed,
   663→    #[msg("Reveal does not match commit hash")]
   664→    InvalidReveal,
   665→    #[msg("No consensus reached")]
   666→    NoConsensus,
   667→    #[msg("Market has not been resolved")]
   668→    MarketNotResolved,
   669→    #[msg("Vote has not been revealed")]
   670→    VoteNotRevealed,
   671→    #[msg("Reputation already settled for this vote")]
   672→    AlreadySettled,
   673→    #[msg("Arithmetic overflow")]
   674→    ArithmeticOverflow,
   675→    #[msg("Invalid voting round")]
   676→    InvalidRound,
   677→    #[msg("Bet amount must be greater than zero")]
   678→    ZeroBetAmount,
   679→    #[msg("Betting window is closed")]
   680→    BettingWindowClosed,
   681→    #[msg("Payout already claimed")]
   682→    AlreadyClaimed,
   683→    #[msg("Bet outcome did not match the resolved outcome")]
   684→    BetDidNotWin,
   685→    #[msg("Reveal window has not closed yet — wait until after reveal_deadline")]
   686→    RevealWindowNotClosed,
   687→    #[msg("Caller is not authorized to perform this action")]
   688→    Unauthorized,
   689→}
   690→
   691→pub fn commitment_hash(outcome: u8, salt: &[u8; 32]) -> [u8; 32] {
   692→    hashv(&[&[outcome], salt]).to_bytes()
   693→}
   694→
   695→pub fn verify_commitment(outcome: u8, salt: &[u8; 32], commit_hash: &[u8; 32]) -> bool {
   696→    commitment_hash(outcome, salt) == *commit_hash
   697→}
   698→
   699→pub fn consensus_outcome(
   700→    total_reveals: u32,
   701→    yes_reveals: u32,
   702→    no_reveals: u32,
   703→    min_votes: u16,
   704→    consensus_bps: u16,
   705→) -> Option<u8> {
   706→    if total_reveals < u32::from(min_votes) || yes_reveals == no_reveals {
   707→        return None;
   708→    }
   709→
   710→    let (candidate, votes) = if yes_reveals > no_reveals {
   711→        (OUTCOME_YES, yes_reveals)
   712→    } else {
   713→        (OUTCOME_NO, no_reveals)
   714→    };
   715→
   716→    let vote_bps = u128::from(votes) * 10_000;
   717→    let required_bps = u128::from(total_reveals) * u128::from(consensus_bps);
   718→    if vote_bps >= required_bps {
   719→        Some(candidate)
   720→    } else {
   721→        None
   722→    }
   723→}
   724→
   725→fn is_binary_outcome(outcome: u8) -> bool {
   726→    outcome == OUTCOME_YES || outcome == OUTCOME_NO
   727→}
   728→
   729→#[cfg(test)]
   730→mod tests {
   731→    use super::*;
   732→
   733→    #[test]
   734→    fn commitment_hash_round_trips() {
   735→        let salt = [7; 32];
   736→        let commit = commitment_hash(OUTCOME_YES, &salt);
   737→
   738→        assert!(verify_commitment(OUTCOME_YES, &salt, &commit));
   739→        assert!(!verify_commitment(OUTCOME_NO, &salt, &commit));
   740→    }
   741→
   742→    #[test]
   743→    fn consensus_requires_min_votes() {
   744→        assert_eq!(consensus_outcome(2, 2, 0, 3, 7_000), None);
   745→    }
   746→
   747→    #[test]
   748→    fn consensus_requires_threshold() {
   749→        assert_eq!(consensus_outcome(3, 2, 1, 3, 7_000), None);
   750→        assert_eq!(consensus_outcome(4, 3, 1, 3, 7_000), Some(OUTCOME_YES));
   751→    }
   752→
   753→    #[test]
   754→    fn consensus_rejects_ties() {
   755→        assert_eq!(consensus_outcome(4, 2, 2, 3, 7_000), None);
   756→    }
   757→
   758→    // ── Payout math tests ────────────────────────────────────────────────────
   759→
   760→    fn payout(bet_amount: u64, yes_pool: u64, no_pool: u64, winner: u8) -> u64 {
   761→        let total_pool = yes_pool + no_pool;
   762→        let winning_pool = if winner == OUTCOME_YES { yes_pool } else { no_pool };
   763→        ((bet_amount as u128) * (total_pool as u128) / (winning_pool as u128)) as u64
   764→    }
   765→
   766→    #[test]
   767→    fn payout_winner_takes_all_when_only_side() {
   768→        // 100 tokens bet YES, 0 bet NO → YES wins, bettor gets 100 back
   769→        let p = payout(100, 100, 0, OUTCOME_YES);
   770→        assert_eq!(p, 100);
   771→    }
   772→
   773→    #[test]
   774→    fn payout_proportional_split() {
   775→        // 100 YES, 100 NO → total 200; YES wins; bettor with 50 YES gets 100
   776→        let p = payout(50, 100, 100, OUTCOME_YES);
   777→        assert_eq!(p, 100);
   778→    }
   779→
   780→    #[test]
   781→    fn payout_minority_winner_gets_more() {
   782→        // 25 YES, 75 NO → total 100; YES wins; bettor with 25 YES gets 100
   783→        let p = payout(25, 25, 75, OUTCOME_YES);
   784→        assert_eq!(p, 100);
   785→    }
   786→
   787→    #[test]
   788→    fn payout_partial_yes_bet() {
